function validate([nums, space]) {
  if (!Array.isArray(nums) || nums.length < 1 || nums.length > 100000) return 'nums needs 1 to 10^5 values.';
  if (nums.some(v => !Number.isInteger(v) || v < 1 || v > 1e9)) return 'Each value of nums is an integer from 1 to 10^9.';
  if (!Number.isInteger(space) || space < 1 || space > 1e9) return 'space is an integer from 1 to 10^9.';
  return null;
}

