function generate(rand, size) {
  const pick = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  if (size === 'large') {
    const n = 2000;
    const space = rand() < 0.8 ? pick(1, 2500) : pick(1, 1e9);
    const nums = Array.from({ length: n }, () => pick(1, 1e9));
    return [nums, space];
  }
  const n = pick(1, 8);
  const space = pick(1, 6);
  const nums = Array.from({ length: n }, () => pick(1, 20));
  return [nums, space];
}
